import { computed, inject, Injectable } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { NavigationEnd, Router } from '@angular/router';
import { filter, map } from 'rxjs';
import { ThemeService } from './theme.service';

export interface NavItem {
  readonly label: string;
  readonly path: string;
  readonly icon: string;
}

export interface Crumb {
  readonly label: string;
  readonly path?: string;
}

// The six rail destinations. Hero detail is reached from the roster, not the rail.
const NAV_ITEMS: readonly NavItem[] = [
  { label: 'Dashboard', path: '/dashboard', icon: 'lucideLayoutDashboard' },
  { label: 'Roster', path: '/roster', icon: 'lucideUsers' },
  { label: 'Missions', path: '/missions', icon: 'lucideTarget' },
  { label: 'Threats', path: '/threats', icon: 'lucideShieldAlert' },
  { label: 'Recruit', path: '/recruit', icon: 'lucideUserPlus' },
  { label: 'Settings', path: '/settings', icon: 'lucideSettings' },
];

const SECTION_LABELS: Readonly<Record<string, string>> = {
  dashboard: 'Dashboard',
  roster: 'Roster',
  detail: 'Hero Detail',
  missions: 'Missions',
  threats: 'Threats',
  recruit: 'Recruit',
  settings: 'Settings',
};

@Injectable()
export class AppShellViewModel {
  private readonly router = inject(Router);
  private readonly theme = inject(ThemeService);

  private readonly url = toSignal(
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
      map((event) => event.urlAfterRedirects),
    ),
    { initialValue: this.router.url },
  );

  readonly nav = NAV_ITEMS;

  readonly darkMode = this.theme.dark;

  readonly crumbs = computed<readonly Crumb[]>(() => {
    const section = this.url().split(/[/?#]/).filter(Boolean)[0] ?? 'dashboard';
    const parent: readonly Crumb[] = section === 'detail' ? [{ label: 'Roster', path: '/roster' }] : [];
    return [{ label: 'Hero Ops', path: '/dashboard' }, ...parent, { label: SECTION_LABELS[section] ?? 'Dashboard' }];
  });

  toggleTheme(): void {
    this.theme.toggle();
  }
}
==== shell/theme.service.ts
import { computed, DOCUMENT, effect, inject, Injectable, signal } from '@angular/core';

export type ThemeChoice = 'light' | 'dark';

const STORAGE_KEY = 'hero-ops-theme';

// App-wide singleton: the theme is one document-level setting, not screen state.
// Until the user chooses, the operating system's colour scheme decides.
@Injectable({ providedIn: 'root' })
export class ThemeService {
  private readonly document = inject(DOCUMENT);
  private readonly window = this.document.defaultView;
  private readonly systemQuery = this.window?.matchMedia?.('(prefers-color-scheme: dark)') ?? null;

  private readonly stored = signal<ThemeChoice | null>(this.readStored());
  private readonly systemDark = signal(this.systemQuery?.matches ?? false);

  readonly dark = computed(() => (this.stored() ?? (this.systemDark() ? 'dark' : 'light')) === 'dark');

  constructor() {
    this.systemQuery?.addEventListener('change', (event) => this.systemDark.set(event.matches));

    effect(() => {
      this.document.documentElement.classList.toggle('dark', this.dark());
    });
  }

  toggle(): void {
    this.choose(this.dark() ? 'light' : 'dark');
  }

  private choose(theme: ThemeChoice): void {
    this.stored.set(theme);
    this.window?.localStorage.setItem(STORAGE_KEY, theme);
  }

  private readStored(): ThemeChoice | null {
    const value = this.window?.localStorage.getItem(STORAGE_KEY);
    return value === 'light' || value === 'dark' ? value : null;
  }
}
==== forms/form-field-meta.ts
/**
 * Presentation metadata that rides on a zod field via `.meta()`. Strongly typed,
 * so a missing label is a compile error rather than a runtime surprise. A form
 * component reads this off the schema instead of restating labels and control
 * kinds in a parallel config object.
 */
export type ControlKind = 'text' | 'email' | 'number' | 'select' | 'checkbox' | 'textarea';

export interface FormFieldMeta {
  label: string;
  control: ControlKind;
  placeholder?: string;
  options?: ReadonlyArray<{ value: string; label: string }>;
  order?: number;
  help?: string;
}
==== forms/zod-meta.ts
import type { z } from 'zod';
import type { FormFieldMeta } from './form-field-meta';

/**
 * Read the FormFieldMeta off each field of a zod object schema. Keeps the label,
 * control kind, and placeholder on the schema (one source of truth) so a form
 * component reads them instead of restating them. Pair with `validateStandardSchema`
 * from `@angular/forms/signals` for validation, so shape, rules, and labels all
 * live on the one schema.
 */
export function formMeta(schema: z.ZodObject<z.ZodRawShape>): Record<string, FormFieldMeta> {
  const meta: Record<string, FormFieldMeta> = {};
  for (const [name, field] of Object.entries(schema.shape)) {
    meta[name] = (field as z.ZodType).meta() as unknown as FormFieldMeta;
  }
  return meta;
}

