import { z } from 'zod';
import { HERO_STATUSES, POWER_CLASSES } from '../domain/hero.model';
import type { FormFieldMeta } from '../forms/form-field-meta';

// The hero dossier edit form. This schema is the single source of truth for the
// shape, the rules, and the field labels. The form reads labels off `.meta()`.
// Status is a select, not a switch: a boolean cannot carry Injured, Reserve, or MIA.
export const heroSchema = z.object({
  name: z
    .string()
    .trim()
    .min(1, 'Name is required')
    .max(40, 'Name must be 40 characters or fewer')
    .meta({ label: 'Hero name', control: 'text', order: 1 } satisfies FormFieldMeta),
  alias: z
    .string()
    .trim()
    .min(1, 'Alias is required')
    .max(40, 'Alias must be 40 characters or fewer')
    .meta({ label: 'Alias', control: 'text', order: 2 } satisfies FormFieldMeta),
  powerClass: z
    .enum(POWER_CLASSES)
    .meta({
