            <h2 hlmCardTitle id="edit-title">Edit dossier</h2>
          </div>
          <div hlmCardContent>
            <form class="detail__form" novalidate (submit)="$event.preventDefault(); vm.save()">
              <div class="detail__fields">
                <hlm-field>
                  <label hlmFieldLabel for="edit-name">{{ vm.meta['name'].label }}</label>
                  <input hlmInput id="edit-name" [formField]="vm.form.name" />
                  @for (error of vm.form.name().errors(); track error.kind) {
                    <hlm-field-error>{{ error.message }}</hlm-field-error>
                  }
                </hlm-field>

                <hlm-field>
                  <label hlmFieldLabel for="edit-alias">{{ vm.meta['alias'].label }}</label>
                  <input hlmInput id="edit-alias" [formField]="vm.form.alias" />
                  @for (error of vm.form.alias().errors(); track error.kind) {
                    <hlm-field-error>{{ error.message }}</hlm-field-error>
                  }
                </hlm-field>

                <hlm-field>
                  <label hlmFieldLabel for="edit-power-class">{{ vm.meta['powerClass'].label }}</label>
                  <hlm-select [value]="vm.dossier().powerClass" (valueChange)="vm.setPowerClass($event)">
                    <hlm-select-trigger buttonId="edit-power-class" class="detail__select">
                      <hlm-select-value />
                    </hlm-select-trigger>
                    <hlm-select-content *hlmSelectPortal>
                      @for (option of vm.meta['powerClass'].options ?? []; track option.value) {
                        <hlm-select-item [value]="option.value">{{ option.label }}</hlm-select-item>
                      }
                    </hlm-select-content>
                  </hlm-select>
                </hlm-field>

                <hlm-field>
                  <label hlmFieldLabel for="edit-power-index">{{ vm.meta['powerIndex'].label }}</label>
                  <input hlmInput id="edit-power-index" type="number" [formField]="vm.form.powerIndex" />
                  <hlm-field-description>{{ vm.meta['powerIndex'].help }}</hlm-field-description>
                  @for (error of vm.form.powerIndex().errors(); track error.kind) {
                    <hlm-field-error>{{ error.message }}</hlm-field-error>
                  }
                </hlm-field>

                <hlm-field>
                  <label hlmFieldLabel for="edit-status">{{ vm.meta['status'].label }}</label>
                  <hlm-select [value]="vm.dossier().status" (valueChange)="vm.setStatus($event)">
                    <hlm-select-trigger buttonId="edit-status" class="detail__select">
                      <hlm-select-value />
                    </hlm-select-trigger>
                    <hlm-select-content *hlmSelectPortal>
                      @for (option of vm.meta['status'].options ?? []; track option.value) {
                        <hlm-select-item [value]="option.value">{{ option.label }}</hlm-select-item>
                      }
                    </hlm-select-content>
                  </hlm-select>
                </hlm-field>

                <hlm-field class="detail__wide">
                  <label hlmFieldLabel for="edit-notes">{{ vm.meta['notes'].label }}</label>
                  <textarea hlmTextarea id="edit-notes" rows="4" [formField]="vm.form.notes"></textarea>
                  @for (error of vm.form.notes().errors(); track error.kind) {
                    <hlm-field-error>{{ error.message }}</hlm-field-error>
                  }
                </hlm-field>
              </div>

              <div class="detail__form-actions">
                @if (vm.saved()) {
                  <p role="status" class="detail__saved">Dossier saved.</p>
                }
                <button hlmBtn variant="outline" type="button" (click)="vm.cancel()">Cancel</button>
                <button hlmBtn type="submit">Save changes</button>
              </div>
            </form>
          </div>
        </section>
      </div>
    </hlm-tabs>
  } @else {
    <section class="detail__names" aria-labelledby="missing-title">
      <h1 id="missing-title" class="detail__title">Hero not found</h1>
      <p class="detail__alias">No hero on the roster has the ID in this link.</p>
    </section>
  }
</section>

