};

function dossierOf(hero: Hero): HeroDossierModel {
  return {
    name: hero.name,
    alias: hero.alias,
    powerClass: hero.powerClass,
    powerIndex: hero.powerIndex,
    status: hero.status,
    notes: hero.notes,
  };
}

